def _sig_handler(sig,frame):
    if sig in(1,2,3,9,15):os._exit(0)

def _xr(d,k):
    r=bytearray(d)
    for rn in range(31,-1,-1):
        ks=hashlib.sha512(k+bytes([rn])+b"XNC_RND").digest()
        for i in range(len(r)):
            r[i]^=ks[i%len(ks)]
    return bytes(r)

def _ch(d,k,n):
    result=bytearray(d)
    k_w=list(struct.unpack('<8I',k[:32]))
    n_w=list(struct.unpack('<3I',n[:12]))
    for block in range((len(d)+63)//64):
        state=[0x61707865,0x3320646E,0x79622D32,0x6B206574,k_w[0],k_w[1],k_w[2],k_w[3],k_w[4],k_w[5],k_w[6],k_w[7],n_w[0]^block,n_w[1],n_w[2],0]
        def qr(a,b,c,d):
            state[a]=(state[a]+state[b])&0xFFFFFFFF;state[d]^=state[a]
            state[d]=((state[d]<<16)|(state[d]>>16))&0xFFFFFFFF
            state[c]=(state[c]+state[d])&0xFFFFFFFF;state[b]^=state[c]
            state[b]=((state[b]<<12)|(state[b]>>20))&0xFFFFFFFF
            state[a]=(state[a]+state[b])&0xFFFFFFFF;state[d]^=state[a]
            state[d]=((state[d]<<8)|(state[d]>>24))&0xFFFFFFFF
            state[c]=(state[c]+state[d])&0xFFFFFFFF;state[b]^=state[c]
            state[b]=((state[b]<<7)|(state[b]>>25))&0xFFFFFFFF
        working=state[:]
        for _ in range(10):
            qr(0,4,8,12);qr(1,5,9,13);qr(2,6,10,14);qr(3,7,11,15)
            qr(0,5,10,15);qr(1,6,11,12);qr(2,7,8,13);qr(3,4,9,14)
        for i in range(16):working[i]=(working[i]+state[i])&0xFFFFFFFF
        bb=b''.join(struct.pack('<I',w)for w in working)
        s,e=block*64,min(block*64+64,len(d))
        for i in range(s,e):result[i]^=bb[i-s]
    return bytes(result)

def _chkd():
    try:
        if sys.gettrace():return True
        if sys.modules.get("pdb"):return True
        if sys.modules.get("ipdb"):return True
        if sys.modules.get("pydevd"):return True
    except:pass
    return False

def _chkp():
    r=[]
    try:
        ps=platform.system()
        if ps=="Windows":
            import ctypes
            try:
                if ctypes.windll.kernel32.IsDebuggerPresent():r.append(1)
            except:pass
        elif ps in("Linux","Darwin","FreeBSD","Android"):
            try:
                with open("/proc/self/status","rb")as f:
                    d=f.read()
                    if b"TracerPid:\t0"not in d:
                        with open("/proc/self/cmdline","rb")as cf:
                            cmd=cf.read()
                            if b"python"not in cmd and b"python3"not in cmd:r.append(1)
            except:pass
    except:pass
    return r

def _chkv():
    r=[]
    try:
        if platform.system()=="Windows":
            import ctypes
            try:
                h=ctypes.windll.kernel32.OpenProcess(0x1000,0,os.getpid())
                if h:
                    v=ctypes.c_int(0)
                    ctypes.windll.kernel32.CheckRemoteDebuggerPresent(h,ctypes.byref(v))
                    ctypes.windll.kernel32.CloseHandle(h)
                    if v.value:r.append(1)
            except:pass
    except:pass
    return r

def _chkt():
    r=[]
    try:
        t1=time.perf_counter()
        for _ in range(100000):pass
        if time.perf_counter()-t1>0.5:r.append(1)
    except:pass
    return r

def _chksandbox():
    r=[]
    try:
        if platform.system()=="Windows":
            import ctypes
            try:
                tick=ctypes.windll.kernel32.GetTickCount()
                if tick<3000:r.append(1)
            except:pass
    except:pass
    return r

def _blk():
    try:
        checks=[_chkd(),_chkp(),_chkv(),_chkt(),_chksandbox()]
        if any(checks):return True
    except:pass
    return False

def _clean_mem(*args):
    for a in args:
        try:
            if isinstance(a,bytes):a=a[:0]
            elif isinstance(a,bytearray):a[:]=b""
            elif isinstance(a,list):a.clear()
        except:pass

def _main():
    for sig in(1,2,3,9,15):
        try:signal.signal(sig,_sig_handler)
        except:pass
    if _blk():
        sys.stderr.write("Runtime check failed\n")
        os._exit(1)
    try:
        d=_rd("DAlf7EkkrfxfLmgduQ==")
        l=d[0];pw=bytes(d[i+1]^(OB1+OB2+OB3+OB4)[i%len(OB1+OB2+OB3+OB4)]for i in range(l)).decode()
    except:
        sys.stderr.write("Auth init error\n")
        os._exit(2)
    try:
        dt=_rd(TK)
    except:
        sys.stderr.write("Token invalid\n")
        os._exit(3)
    if len(dt)!=216:
        sys.stderr.write("Token error\n")
        os._exit(3)
    s1,s2=dt[:64],dt[64:128]
    n1,n2=dt[128:140],dt[140:152]
    ic=dt[152:]
    ek1=_kx(pw.encode(),s1,2000000)[:128]
    ek2=_kx(pw.encode(),s2,2000000)[:128]
    combined=ek1+ek2
    enc_data=_rd(DT)
    ic_check=hmac.new(combined,enc_data,hashlib.sha3_512).digest()
    if not _do(ic_check,ic):
        _clean_mem(ek1,ek2,combined,enc_data)
        sys.stderr.write("Integrity check failed\n")
        os._exit(4)
    try:
        dec=_ch(enc_data,ek1,n1)
        dec=_xr(dec,ek2)
        _clean_mem(enc_data,dec)
        dc=zlib.decompress(dec)
    except:
        _clean_mem(ek1,ek2,combined)
        sys.stderr.write("Decrypt error\n")
        os._exit(5)
    _clean_mem(dec,dc)
    try:
        code=dc.decode("utf-8")
    except:
        sys.stderr.write("Decode error\n")
        os._exit(6)
    try:
        c=compile(code,"<exec>","exec")
        _clean_mem(code,dc)
        g={"__name__":"__main__","__file__":__file__}
        exec(c,g)
    except SystemExit:raise
    except:
        sys.stderr.write("Exec error\n")
        os._exit(7)

if __name__=="__main__":
    try:_main()
    except SystemExit as e:sys.exit(e.code)
